/**
 * The church logo's outline (SDALogoShape.swift, generated by
 * Tools/make_splash_logo.swift from Tools/source/sda-logo.svg), in unit
 * coordinates. Fill it even-odd: the cross and the gaps between the flame
 * strokes are holes. res/drawable/splash_logo.xml is the same outline.
 */
object SDALogoShape {
    /** Width over height of the logo's ink. */
    const val ASPECT_RATIO = 1.0864f
    /** Centre of the largest disc inside the ink, for zooming into the mark (unit point). */
    val revealAnchor = Offset(0.3398f, 0.8548f)
    /** That disc's radius, as a fraction of the logo's width. */
    const val REVEAL_RADIUS = 0.0709f

    /** The outline stretched to fill [rect], even-odd. */
    fun path(rect: Rect): Path {
        val path = Path().apply { fillType = PathFillType.EvenOdd }
        val t = DATA.split(' ')
        var i = 0
        fun x() = rect.left + t[i++].toFloat() * rect.width
        fun y() = rect.top + t[i++].toFloat() * rect.height
        while (i < t.size) {
            when (t[i++]) {
                "M" -> path.moveTo(x(), y())
                "C" -> path.cubicTo(x(), y(), x(), y(), x(), y())
                "Z" -> path.close()
            }
        }
        return path
    }

